// path: src/App.tsx

import { useEffect, useRef } from 'react'
import { ThemeProvider } from './themes/ThemeProvider'
import { AppManager } from './core/AppManager'
import { useGlobalStore } from './store/useGlobalStore'

export default function App() {
  const loadFromBackend = useGlobalStore((s) => s.loadFromBackend)
  const isOnline = useGlobalStore((s) => s.isOnline)

  // Track previous online state so we can detect offline → online recovery
  const wasOnlineRef = useRef<boolean>(true)

  // ── 1. Initial hydration on cold mount ────────────────────────────────────
  useEffect(() => {
    loadFromBackend()
  }, [loadFromBackend])

  // ── 2. Periodic background re-hydration every 60 seconds ─────────────────
  // Keeps currency, inventory and vault in sync without requiring F5.
  useEffect(() => {
    const timer = setInterval(() => {
      loadFromBackend()
    }, 60_000)
    return () => clearInterval(timer)
  }, [loadFromBackend])

  // ── 3. Tab-focus re-hydration via Page Visibility API ─────────────────────
  // Re-syncs the moment the user switches back to this tab.
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        loadFromBackend()
      }
    }
    document.addEventListener('visibilitychange', handleVisibilityChange)
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange)
  }, [loadFromBackend])

  // ── 4. Online-recovery re-hydration ───────────────────────────────────────
  // When the backend flips from offline → online, immediately re-hydrate
  // to pick up any mutations that happened while we were disconnected.
  useEffect(() => {
    const wasOffline = !wasOnlineRef.current
    if (wasOffline && isOnline) {
      loadFromBackend()
    }
    wasOnlineRef.current = isOnline
  }, [isOnline, loadFromBackend])

  return (
    <ThemeProvider>
      <AppManager />
    </ThemeProvider>
  )
}

// path: src/store/useGlobalStore.ts

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import { hydrateAllStores, persistState } from '../core/syncEngine'
import { checkBackendHealth, getBackendStatus } from '../core/api'
import type { AppManifest } from '../core/types'

/** All apps registered in Universe 25. Plugin folders in src/apps are discovered dynamically. */
export const APP_REGISTRY: AppManifest[] = [
  { id: 'golden-hour', name: 'Golden Hour', icon: '✨', description: 'Universal Stake Nexus • Babylonian Altar' },
  { id: 'vinyl-angel', name: 'Vinyl Angel', icon: '💿', description: 'Autonomous Music Laboratory' },
  { id: 'arc-jurassic', name: 'ARC Jurassic', icon: '🦕', description: 'Dino Collector & Battler' },
  { id: 'heraclitus', name: 'Heraclitus', icon: '🌀', description: 'Eternal Flux & Chrono Engine • Panta Rhei' },
  // Plugin architecture: deleted folders (farm-a, farm-b) should not crash the app.
  // If restored, they are loaded as plugin tabs automatically.
]

interface GlobalState {
  // Navigation (Transient UI State)
  activeApp: string
  setActiveApp: (appId: string) => void

  // User profile
  userProfile: { name: string; avatar: string; createdAt: string } | null
  setUserProfile: (profile: GlobalState['userProfile']) => void

  // Hydration & Connection Status
  isLoaded: boolean
  isLoading: boolean
  backendError: string | null
  isOnline: boolean
  lastSavedAt: string | null

  // Backend I/O
  loadFromBackend: () => Promise<void>
  saveToBackend: (snapshot: Record<string, unknown>) => Promise<void>
}

export const useGlobalStore = create<GlobalState>()(
  persist(
    (set) => ({
      activeApp: 'golden-hour',
      setActiveApp: (appId) => set({ activeApp: appId }),

      userProfile: null,
      setUserProfile: (profile) => set({ userProfile: profile }),

      isLoaded: false,
      isLoading: false,
      backendError: null,
      isOnline: true,
      lastSavedAt: null,

      loadFromBackend: async () => {
        set({ isLoading: true, backendError: null })
        try {
          // 1. Authoritative health verification
          const isHealthy = await checkBackendHealth()
          if (!isHealthy) {
            const status = getBackendStatus()
            const errorMsg = status.lastError || 'Backend storage engine is offline or unreachable at http://localhost:8080'
            set({
              isLoaded: false,
              isLoading: false,
              isOnline: false,
              backendError: errorMsg,
            })
            console.error(`[GlobalStore] Backend Health Check Failed: ${errorMsg}`)
            return
          }

          // 2. Authoritative hydration across all stores
          await hydrateAllStores()

          set({
            isLoaded: true,
            isLoading: false,
            isOnline: true,
            backendError: null,
          })
        } catch (err) {
          const errorMsg = err instanceof Error ? err.message : 'Failed to hydrate game state from backend'
          set({
            isLoaded: false,
            isLoading: false,
            isOnline: false,
            backendError: errorMsg,
          })
          console.error(`[GlobalStore] Hydration Critical Failure: ${errorMsg}`)
        }
      },

      saveToBackend: async (snapshot) => {
        try {
          await persistState(snapshot)
          set({ lastSavedAt: new Date().toISOString(), backendError: null, isOnline: true })
        } catch (err) {
          const errorMsg = err instanceof Error ? err.message : 'Failed to persist state snapshot to backend'
          set({ backendError: errorMsg, isOnline: false })
          console.error(`[GlobalStore] Save Failed: ${errorMsg}`)
          throw err
        }
      },
    }),
    {
      name: 'universe25-transient-ui',
      partialize: (state) => ({ activeApp: state.activeApp }), // Strictly restrict local storage to transient UI state
    },
  ),
)

// path: src/core/api.ts

import type { ApiRequest, ApiResponse } from './types'

export const API_BASE = 'http://localhost:8080'
export const DEFAULT_PROJECT_ID = 'universe_25'

export interface BackendStatus {
  isOnline: boolean
  lastCheckedAt: string | null
  lastError: string | null
}

let currentStatus: BackendStatus = {
  isOnline: true,
  lastCheckedAt: null,
  lastError: null,
}

type StatusListener = (status: BackendStatus) => void
const statusListeners = new Set<StatusListener>()

export function getBackendStatus(): BackendStatus {
  return currentStatus
}

export function subscribeBackendStatus(listener: StatusListener): () => void {
  statusListeners.add(listener)
  listener(currentStatus)
  return () => {
    statusListeners.delete(listener)
  }
}

function updateStatus(isOnline: boolean, error: string | null = null) {
  currentStatus = {
    isOnline,
    lastCheckedAt: new Date().toISOString(),
    lastError: error,
  }
  statusListeners.forEach((listener) => listener(currentStatus))
}

/**
 * Health check to verify if the Blue Rose backend storage engine is running.
 */
export async function checkBackendHealth(): Promise<boolean> {
  try {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 8000)

    const res = await fetch(`${API_BASE}/health`, {
      method: 'GET',
      signal: controller.signal,
    })
    clearTimeout(timeoutId)

    if (res.ok) {
      updateStatus(true, null)
      return true
    } else {
      const errText = `Backend returned HTTP status ${res.status}`
      updateStatus(false, errText)
      return false
    }
  } catch (err) {
    const errText = err instanceof Error ? err.message : 'Backend connection failed'
    updateStatus(false, errText)
    return false
  }
}

/**
 * Single reusable function for all backend communication.
 * Every call goes through POST /api/v1/execute.
 * Never silently swallows errors!
 */
export async function execute<T = unknown>(
  tier: string,
  action: string,
  key?: string,
  data?: unknown,
  projectId: string = DEFAULT_PROJECT_ID
): Promise<ApiResponse<T>> {
  const body: ApiRequest = {
    project_id: projectId,
    tier,
    order: { action, ...(key && { key }), ...(data !== undefined && { data }) },
  }

  try {
    const res = await fetch(`${API_BASE}/api/v1/execute`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })

    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }))
      const errorMsg = err.detail || `API error HTTP ${res.status}`
      updateStatus(false, errorMsg)
      throw new Error(`[Backend Engine Error] ${errorMsg}`)
    }

    const json = await res.json()
    updateStatus(true, null)
    return json
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Network failure contacting backend'
    updateStatus(false, errorMsg)
    throw new Error(`[Backend Unreachable] ${errorMsg}`)
  }
}

