// path: src/apps/vinyl-angel/store/useVinylStore.ts

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { VinylLocalTheme, VinylPlayerSettings, VinylSessionStats, ShopItem, PlaylistItem, Tier2EventEntry, CustomPlaylist, ChannelOriginItem, ChannelStatus } from '../types';
import { useInventoryStore } from '../../../store/useInventoryStore';

export const SHOP_CATALOG: ShopItem[] = [
  {
    id: 'angel-roll-ticket',
    name: 'Angel Roll Ticket 🎟️',
    description: 'Dimensional summoning ticket forged from 25 Celestial Discs. Used in the Grand Dimensional Nexus (Modern Day world) where valuable objects of all dimensions converge.',
    category: 'ticket',
    priceDiscs: 25,
    rewardTicket: 'angel-roll',
    isLocked: false,
    iconName: 'Ticket',
    color: '#ffd86b',
    perkEffect: 'Summons celestial artifacts & relics in Modern Day.',
    consumable: true,
  },
  {
    id: 'solar-flora-ticket',
    name: 'Solar Flora Ticket 🌻',
    description: 'Extracted from the high-yield solar crops of Farm Beta. Awaiting Modern Day convergence.',
    category: 'ticket',
    priceDiscs: 50,
    isLocked: true,
    lockReason: 'Dimension Locked: Farm Alpha/Beta Nexus',
    iconName: 'Sparkles',
    color: '#fbbf24',
    perkEffect: 'Flora bio-essence synthesizer.',
  },
  {
    id: 'codex-relic-ticket',
    name: 'Codex Relic Ticket 📖',
    description: 'Ancient cipher tablet from the Artifact Codex archive. Sealed until dimensional breach.',
    category: 'ticket',
    priceDiscs: 50,
    isLocked: true,
    lockReason: 'Dimension Locked: Artifact Codex Matrix',
    iconName: 'Shield',
    color: '#a78bfa',
    perkEffect: 'Decodes lost hazard protocols.',
  },
  {
    id: 'golden-stylus',
    name: 'Golden Stylus 🪽',
    description: 'A handcrafted needle forged in celestial gold. Bestows gilded glow across the player interface.',
    category: 'cosmetic',
    priceDiscs: 100,
    isLocked: true,
    lockReason: 'Modern Day Nexus Crafting Required',
    iconName: 'Sparkles',
    color: '#ffd86b',
    perkEffect: 'Gilded player borders and audio visual sparkle effects.',
  },
  {
    id: 'abyssal-needle',
    name: 'Abyssal Needle ✦',
    description: 'A needle crafted from collapsed dark matter. Unlocks cosmic event horizon pulses.',
    category: 'cosmetic',
    priceDiscs: 150,
    isLocked: true,
    lockReason: 'Modern Day Nexus Crafting Required',
    iconName: 'Moon',
    color: '#a78bfa',
    perkEffect: 'Deep void pulses on each track transition.',
  },
  {
    id: 'time-multiplier-2x',
    name: 'Harmonic Catalyst (Boost)',
    description: 'Doubles the resonance generated for rated songs.',
    category: 'booster',
    priceDiscs: 60,
    isLocked: true,
    lockReason: 'Modern Day Nexus Crafting Required',
    iconName: 'Zap',
    color: '#38bdf8',
    perkEffect: 'Multiplies harmonic disc output.',
    consumable: true,
  },
];

interface VinylStoreState {
  // Currencies
  discs: number;
  angelRollTickets: number;

  // Theming & Cosmetics
  localTheme: VinylLocalTheme;
  unlockedThemes: VinylLocalTheme[];
  purchasedItemIds: string[];
  equippedStylus: string | null;
  boosterCharges: number;

  // Settings & Session Stats
  settings: VinylPlayerSettings;
  stats: VinylSessionStats;

  // Inter-tab Transfer State
  queuedTrackForGameplay: PlaylistItem | null;
  queuedPlaylistForGameplay: string | null;

  // Resilient Offline Event Outbox
  offlineOutbox: Tier2EventEntry[];

  // Sovereign Custom Playlists (Channel Federations)
  customPlaylists: CustomPlaylist[];

  // Shared Channel & Metadata State (synchronized across all tabs)
  channelList: ChannelOriginItem[];
  channelMetaMap: Record<string, { status: ChannelStatus; notes?: string }>;

  // Blocked Songs State (immediate pool exclusion)
  blockedSongIds: string[];

  // Actions
  earnDiscs: (count: number) => void;
  spendDiscs: (count: number) => boolean;
  addAngelTickets: (count: number) => void;
  spendAngelTickets: (count: number) => boolean;

  setLocalTheme: (theme: VinylLocalTheme) => void;
  unlockTheme: (theme: VinylLocalTheme) => void;
  buyShopItem: (item: ShopItem) => boolean;
  equipStylus: (stylusId: string | null) => void;
  consumeBoosterCharge: () => boolean;
  addBoosterCharges: (charges: number) => void;
  updateSettings: (partial: Partial<VinylPlayerSettings>) => void;
  incrementRatingStats: (discsEarned?: number) => void;
  recordSyncCompleted: () => void;
  hasItem: (itemId: string) => boolean;
  setQueuedTrackForGameplay: (track: PlaylistItem | null) => void;
  setQueuedPlaylistForGameplay: (source: string | null) => void;
  enqueueOfflineEvent: (evt: Tier2EventEntry) => void;
  clearOfflineOutbox: () => void;
  removeOfflineEvents: (timestamps: string[]) => void;

  setCustomPlaylists: (playlists: CustomPlaylist[]) => void;
  addCustomPlaylist: (playlist: CustomPlaylist) => void;
  updateCustomPlaylist: (playlist: CustomPlaylist) => void;
  removeCustomPlaylist: (playlistId: string) => void;

  setChannelList: (channels: ChannelOriginItem[]) => void;
  setChannelMetaMap: (metaMap: Record<string, { status: ChannelStatus; notes?: string }>) => void;
  updateChannelStatus: (channelId: string, channelName: string, status: ChannelStatus) => void;

  addBlockedSong: (songId: string) => void;
  isBlocked: (songId: string) => boolean;
  clearBlockedSongs: () => void;
}

export const useVinylStore = create<VinylStoreState>()(
  persist(
    (set, get) => ({
      discs: 0,
      angelRollTickets: 0,
      localTheme: 'celestial-gold',
      unlockedThemes: ['celestial-gold', 'obsidian-abyss'],
      purchasedItemIds: [],
      equippedStylus: 'golden-stylus',
      boosterCharges: 0,
      settings: {
        autoplay: true,
        defaultPassScore: '5+',
        soundEffects: true,
        autoSync: false,
      },
      stats: {
        sessionRatingsCount: 0,
        totalDiscsEarned: 0,
        lastSyncTimestamp: null,
      },
      queuedTrackForGameplay: null,
      offlineOutbox: [],

      earnDiscs: (count: number) => {
        const amount = Math.max(0, count);
        set((s) => ({ discs: s.discs + amount }));
        // Sync to universal inventory
        useInventoryStore.getState().addDiscs(amount);
      },

      spendDiscs: (count: number) => {
        if (get().discs < count) return false;
        set((s) => ({ discs: s.discs - count }));
        useInventoryStore.getState().spendDiscs(count);
        return true;
      },

      addAngelTickets: (count: number) => {
        const amount = Math.max(0, count);
        set((s) => ({ angelRollTickets: s.angelRollTickets + amount }));
        useInventoryStore.getState().addAngelTickets(amount);
      },

      spendAngelTickets: (count: number) => {
        if (get().angelRollTickets < count) return false;
        set((s) => ({ angelRollTickets: s.angelRollTickets - count }));
        useInventoryStore.getState().spendAngelTickets(count);
        return true;
      },

      setLocalTheme: (theme) => {
        if (get().unlockedThemes.includes(theme)) {
          set({ localTheme: theme });
        }
      },

      unlockTheme: (theme) => {
        if (!get().unlockedThemes.includes(theme)) {
          set((s) => ({ unlockedThemes: [...s.unlockedThemes, theme] }));
        }
      },

      buyShopItem: (item) => {
        if (item.isLocked) return false;

        const price = item.priceDiscs ?? 25;
        if (get().discs < price) return false;

        // Deduct Discs
        get().spendDiscs(price);

        if (item.id === 'angel-roll-ticket') {
          get().addAngelTickets(1);
          set((s) => ({
            purchasedItemIds: [...s.purchasedItemIds, item.id],
          }));
          return true;
        }

        return false;
      },

      equipStylus: (stylusId) => set({ equippedStylus: stylusId }),

      consumeBoosterCharge: () => {
        const current = get().boosterCharges;
        if (current > 0) {
          set({ boosterCharges: current - 1 });
          return true;
        }
        return false;
      },

      addBoosterCharges: (charges) =>
        set((s) => ({ boosterCharges: s.boosterCharges + charges })),

      updateSettings: (partial) =>
        set((s) => ({ settings: { ...s.settings, ...partial } })),

      incrementRatingStats: (discsEarned = 3) =>
        set((s) => ({
          stats: {
            ...s.stats,
            sessionRatingsCount: s.stats.sessionRatingsCount + 1,
            totalDiscsEarned: s.stats.totalDiscsEarned + discsEarned,
          },
        })),

      recordSyncCompleted: () =>
        set((s) => ({
          stats: {
            ...s.stats,
            lastSyncTimestamp: new Date().toLocaleTimeString(),
          },
        })),

      hasItem: (itemId) => get().purchasedItemIds.includes(itemId),

      setQueuedTrackForGameplay: (track) => set({ queuedTrackForGameplay: track }),
      queuedPlaylistForGameplay: null,
      setQueuedPlaylistForGameplay: (source) => set({ queuedPlaylistForGameplay: source }),

      customPlaylists: [],
      channelList: [],
      channelMetaMap: {},

      setCustomPlaylists: (playlists) =>
        set({
          customPlaylists: [...playlists].sort((a, b) =>
            a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })
          ),
        }),
      addCustomPlaylist: (playlist) =>
        set((s) => ({
          customPlaylists: [...s.customPlaylists.filter((p) => p.id !== playlist.id), playlist].sort(
            (a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })
          ),
        })),
      updateCustomPlaylist: (playlist) =>
        set((s) => ({
          customPlaylists: s.customPlaylists
            .map((p) => (p.id === playlist.id ? playlist : p))
            .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })),
        })),
      removeCustomPlaylist: (playlistId) =>
        set((s) => ({
          customPlaylists: s.customPlaylists.filter((p) => p.id !== playlistId),
        })),

      blockedSongIds: [],

      setChannelList: (channels) => set({ channelList: channels }),

      setChannelMetaMap: (metaMap) => set({ channelMetaMap: metaMap }),

      updateChannelStatus: (channelId, channelName, status) =>
        set((s) => ({
          channelMetaMap: {
            ...s.channelMetaMap,
            [channelId]: { status },
            [channelName]: { status },
          },
        })),

      addBlockedSong: (songId: string) =>
        set((s) => {
          const current = Array.isArray(s.blockedSongIds) ? s.blockedSongIds : [];
          return {
            blockedSongIds: current.includes(songId) ? current : [...current, songId],
          };
        }),

      isBlocked: (songId: string) => {
        const current = get().blockedSongIds;
        return Array.isArray(current) ? current.includes(songId) : false;
      },

      clearBlockedSongs: () => set({ blockedSongIds: [] }),

      enqueueOfflineEvent: (evt) =>
        set((s) => ({
          offlineOutbox: [...(s.offlineOutbox || []), evt],
        })),

      clearOfflineOutbox: () => set({ offlineOutbox: [] }),

      removeOfflineEvents: (timestamps) => {
        const tsSet = new Set(timestamps);
        set((s) => ({
          offlineOutbox: (s.offlineOutbox || []).filter((e) => !tsSet.has(e.timestamp)),
        }));
      },
    }),
    {
      name: 'universe25-vinyl-angel-store',
      merge: (persistedState: any, currentState) => ({
        ...currentState,
        ...(persistedState || {}),
        blockedSongIds: Array.isArray(persistedState?.blockedSongIds)
          ? persistedState.blockedSongIds
          : [],
        channelList: Array.isArray(persistedState?.channelList)
          ? persistedState.channelList
          : [],
        channelMetaMap:
          persistedState?.channelMetaMap && typeof persistedState.channelMetaMap === 'object'
            ? persistedState.channelMetaMap
            : {},
      }),
    }
  )
);

// path: src/apps/heraclitus/components/YellowPoolTab.tsx

import React, { useState, useEffect } from 'react'
import { Droplet, Plus, TrendingUp, Clock, Calendar } from 'lucide-react'
import { fetchPoolState, depositToPool } from '../services/heraclitusApi'
import type { YellowTimePoolState, PoolTransaction } from '../types'

export const YellowPoolTab: React.FC = () => {
  const [poolState, setPoolState] = useState<YellowTimePoolState | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Deposit form state
  const [depositSeconds, setDepositSeconds] = useState('')
  const [depositSource, setDepositSource] = useState('')
  const [depositCategory, setDepositCategory] = useState('grind')
  const [depositSpeed, setDepositSpeed] = useState('1.0')
  const [depositNotes, setDepositNotes] = useState('')
  const [depositing, setDepositing] = useState(false)

  useEffect(() => {
    loadPoolState()
  }, [])

  async function loadPoolState() {
    setLoading(true)
    setError(null)
    try {
      const state = await fetchPoolState()
      setPoolState(state)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  async function handleDeposit(e: React.FormEvent) {
    e.preventDefault()
    if (!depositSeconds || !depositSource.trim()) {
      setError('Seconds and source are required')
      return
    }

    setDepositing(true)
    setError(null)
    try {
      const state = await depositToPool({
        seconds: parseFloat(depositSeconds),
        source: depositSource.trim(),
        category: depositCategory,
        speed: parseFloat(depositSpeed),
        notes: depositNotes.trim() || undefined,
      })
      setPoolState(state)
      // Reset form
      setDepositSeconds('')
      setDepositSource('')
      setDepositCategory('grind')
      setDepositSpeed('1.0')
      setDepositNotes('')
    } catch (err: any) {
      setError(err.message)
    } finally {
      setDepositing(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <Droplet className="w-12 h-12 text-[#ffd86b] animate-pulse mx-auto mb-3" />
          <p className="text-[#9e8fb3] font-mono text-sm">Loading Yellow Time Pool...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Pool Balance Banner */}
      <div className="bg-gradient-to-br from-[#2a1f3d] to-[#1a1428] border-2 border-[#ffd86b] rounded-2xl p-6">
        <div className="flex items-center gap-3 mb-4">
          <Droplet className="w-6 h-6 text-[#ffd86b]" />
          <h2 className="text-xl font-bold text-[#ffd86b]">Yellow Time Pool</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="bg-[#0c0914]/50 rounded-xl p-4 border border-[#372a4d]">
            <div className="flex items-center gap-2 mb-2">
              <Clock className="w-4 h-4 text-[#9e8fb3]" />
              <span className="text-xs text-[#9e8fb3] font-mono uppercase">Current Balance</span>
            </div>
            <p className="text-2xl font-bold text-[#ffd86b] font-mono">
              {poolState?.formatted_balance || '0s'}
            </p>
            <p className="text-xs text-[#6b5a7f] mt-1">
              {poolState?.balance_seconds.toFixed(0) || 0} seconds
            </p>
          </div>
          <div className="bg-[#0c0914]/50 rounded-xl p-4 border border-[#372a4d]">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-4 h-4 text-[#9e8fb3]" />
              <span className="text-xs text-[#9e8fb3] font-mono uppercase">Total Earned</span>
            </div>
            <p className="text-2xl font-bold text-[#f5f0e8] font-mono">
              {poolState?.formatted_total_earned || '0s'}
            </p>
            <p className="text-xs text-[#6b5a7f] mt-1">
              {poolState?.total_earned_seconds.toFixed(0) || 0} seconds
            </p>
          </div>
        </div>
      </div>

      {/* Deposit Form */}
      <div className="bg-[#171124] border border-[#372a4d] rounded-xl p-6">
        <div className="flex items-center gap-3 mb-4">
          <Plus className="w-5 h-5 text-[#ffd86b]" />
          <h3 className="text-lg font-bold text-[#f5f0e8]">Manual Deposit</h3>
        </div>
        <form onSubmit={handleDeposit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs text-[#9e8fb3] font-mono mb-2 uppercase">
                Seconds Earned
              </label>
              <input
                type="number"
                min="0"
                step="0.01"
                value={depositSeconds}
                onChange={(e) => setDepositSeconds(e.target.value)}
                className="w-full bg-[#0c0914] border border-[#372a4d] rounded-lg px-4 py-3 text-[#f5f0e8] font-mono focus:outline-none focus:border-[#ffd86b] transition-colors"
                placeholder="3600"
                disabled={depositing}
              />
            </div>
            <div>
              <label className="block text-xs text-[#9e8fb3] font-mono mb-2 uppercase">
                Source / Activity
              </label>
              <input
                type="text"
                value={depositSource}
                onChange={(e) => setDepositSource(e.target.value)}
                className="w-full bg-[#0c0914] border border-[#372a4d] rounded-lg px-4 py-3 text-[#f5f0e8] focus:outline-none focus:border-[#ffd86b] transition-colors"
                placeholder="YouTube Grinding"
                disabled={depositing}
              />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs text-[#9e8fb3] font-mono mb-2 uppercase">
                Category
              </label>
              <select
                value={depositCategory}
                onChange={(e) => setDepositCategory(e.target.value)}
                className="w-full bg-[#0c0914] border border-[#372a4d] rounded-lg px-4 py-3 text-[#f5f0e8] font-mono focus:outline-none focus:border-[#ffd86b] transition-colors"
                disabled={depositing}
              >
                <option value="grind">Grind</option>
                <option value="study">Study</option>
                <option value="work">Work</option>
                <option value="practice">Practice</option>
              </select>
            </div>
            <div>
              <label className="block text-xs text-[#9e8fb3] font-mono mb-2 uppercase">
                Speed Multiplier
              </label>
              <select
                value={depositSpeed}
                onChange={(e) => setDepositSpeed(e.target.value)}
                className="w-full bg-[#0c0914] border border-[#372a4d] rounded-lg px-4 py-3 text-[#f5f0e8] font-mono focus:outline-none focus:border-[#ffd86b] transition-colors"
                disabled={depositing}
              >
                <option value="1.0">1.0x</option>
                <option value="1.25">1.25x</option>
                <option value="1.5">1.5x</option>
                <option value="1.75">1.75x</option>
                <option value="2.0">2.0x</option>
              </select>
            </div>
            <div>
              <label className="block text-xs text-[#9e8fb3] font-mono mb-2 uppercase">
                Notes (Optional)
              </label>
              <input
                type="text"
                value={depositNotes}
                onChange={(e) => setDepositNotes(e.target.value)}
                className="w-full bg-[#0c0914] border border-[#372a4d] rounded-lg px-4 py-3 text-[#f5f0e8] focus:outline-none focus:border-[#ffd86b] transition-colors"
                placeholder="Quick notes..."
                disabled={depositing}
              />
            </div>
          </div>
          <button
            type="submit"
            disabled={depositing || !depositSeconds || !depositSource.trim()}
            className="w-full bg-[#ffd86b] hover:bg-[#ffdf8c] disabled:bg-[#4a3f5c] disabled:cursor-not-allowed text-[#0c0914] font-bold py-3 rounded-lg transition-colors flex items-center justify-center gap-2"
          >
            <Plus className="w-5 h-5" />
            {depositing ? 'Depositing...' : 'Deposit Time'}
          </button>
        </form>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-900/20 border border-red-500/50 rounded-lg p-4">
          <p className="text-red-400 text-sm">{error}</p>
        </div>
      )}

      {/* Transaction History */}
      <div className="bg-[#171124] border border-[#372a4d] rounded-xl p-6">
        <div className="flex items-center gap-3 mb-4">
          <Calendar className="w-5 h-5 text-[#ffd86b]" />
          <h3 className="text-lg font-bold text-[#f5f0e8]">Transaction History</h3>
          <span className="ml-auto text-xs text-[#9e8fb3] font-mono">
            {poolState?.transactions.length || 0} entries
          </span>
        </div>
        {poolState?.transactions && poolState.transactions.length > 0 ? (
          <div className="space-y-2 max-h-[500px] overflow-y-auto">
            {poolState.transactions.map((tx) => (
              <TransactionRow key={tx.id} transaction={tx} />
            ))}
          </div>
        ) : (
