  box-shadow:
    0 0 7px #fff,
    0 0 24px #fff,
    0 0 60px rgba(255,220,80,.96),
    0 0 120px rgba(200,140,0,.92);
}
.yp-supernova::after {
  content:"";
  position:absolute; left:50%; top:50%;
  width:100%; height:46px;
  transform:translate(-50%,-50%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,200,60,.58),
    rgba(255,255,200,.96),
    rgba(255,200,60,.58),
    transparent
  );
  filter:blur(10px);
}
.yp-supernova.active {
  animation: ypNova 480ms cubic-bezier(.06,.88,.12,1) forwards;
}
@keyframes ypNova {
  0%  { opacity:0; transform:translate(-50%,-50%) scaleX(0); }
  10% { opacity:1; transform:translate(-50%,-50%) scaleX(.12); }
  34% { opacity:1; transform:translate(-50%,-50%) scaleX(5); }
  62% { opacity:.95; transform:translate(-50%,-50%) scaleX(22); }
  100%{ opacity:0; transform:translate(-50%,-50%) scaleX(52); }
}

/* ── GOLD MATTER EJECTION on deposit ── */
.yp-matter-field {
  position:absolute; inset:0; z-index:55; pointer-events:none;
}
.yp-matter {
  position:absolute; left:50%; top:50%;
  width:var(--sz); height:var(--sz);
  border-radius:50%; opacity:0;
  background:radial-gradient(circle at 30% 30%,#fff 0 12%,#ffe07a 32%,#c87a00 62%,transparent 78%);
  box-shadow:0 0 5px #fff,0 0 14px rgba(255,200,60,.92);
  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(3px);
}
.yp-matter.active {
  animation: ypMatter var(--dur) cubic-bezier(.08,.84,.13,1) forwards;
}
@keyframes ypMatter {
  0%  { opacity:0;  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(3px) scale(.1); }
  10% { opacity:1; }
  75% { opacity:1; }
  100%{ opacity:0;  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(var(--dist)) scale(.42); }
}

/* ── BALANCE READOUT ── */
.yp-readout {
  position:absolute; inset:0;
  display:flex; flex-direction:column;
  align-items:center; justify-content:center;
  pointer-events:none; z-index:60;
  transform-style: preserve-3d;
}

/* ── DISTORTION ── */
.yp-distortion {
  position:absolute;
  width:900px; height:900px;
  border-radius:50%;
  z-index:4; pointer-events:none; opacity:0;
  background:radial-gradient(
    circle,
    transparent 0 17%,
    rgba(200,140,0,.07) 25%,
    transparent 43%
  );
  filter:blur(10px);
}
.yp-distortion.active {
