  transition: background .15s, transform .1s, box-shadow .15s;
  box-shadow: 0 0 32px rgba(255,216,107,.28);
}
.yp-btn:hover:not(:disabled) {
  background: #ffe485;
  box-shadow: 0 0 44px rgba(255,216,107,.45);
}
.yp-btn:active:not(:disabled) {
