    transparent 100%
  );
  box-shadow:
    0 0 22px #000,
    0 0 60px rgba(180,120,0,.35),
    0 0 130px rgba(140,90,0,.18);
}

.yp-ring {
  position: absolute;
  left: 50%; top: 50%;
  width: var(--d);
  height: var(--d);
  border-radius: 50%;
  border: var(--th) solid transparent;
