  opacity: var(--op);
}

.yp-ring-1 { --d:350px; --th:4px; --tilt:69deg; --op:.92;
  border-top-color:   rgba(255,216,107,.95);
  border-right-color: rgba(200,140,0,.90);
  border-bottom-color:rgba(140,90,0,.55);
  filter: drop-shadow(0 0 9px rgba(255,200,60,.9));
  animation: ypR1 2000ms linear infinite;
}
.yp-ring-2 { --d:298px; --th:3px; --tilt:63deg; --op:.84;
  border-left-color:  rgba(255,245,180,.90);
  border-top-color:   rgba(255,200,80,.88);
  border-bottom-color:rgba(160,100,0,.52);
  filter: drop-shadow(0 0 13px rgba(255,220,100,.92));
  animation: ypR2 1350ms linear infinite reverse;
}
.yp-ring-3 { --d:248px; --th:5px; --tilt:57deg; --op:.78;
  border-right-color: rgba(255,255,200,.75);
  border-left-color:  rgba(200,130,0,.90);
  filter: blur(1px) drop-shadow(0 0 15px rgba(255,200,60,.88));
  animation: ypR3 840ms linear infinite;
}
.yp-ring-4 { --d:204px; --th:3px; --tilt:51deg; --op:.64;
  border-top-color:   rgba(255,240,160,.82);
  border-bottom-color:rgba(180,110,0,.86);
  filter: drop-shadow(0 0 11px rgba(255,210,80,.80));
  animation: ypR4 640ms linear infinite reverse;
}

@keyframes ypR1 {
  from { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(0deg); }
  to   { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(360deg); }
}
@keyframes ypR2 {
  from { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(360deg); }
  to   { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(0deg); }
}
@keyframes ypR3 {
  from { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(0deg); }
  to   { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(360deg); }
}
@keyframes ypR4 {
  from { transform: translate(-50%,-50%) rotateX(51deg) rotateZ(360deg); }
  to   { transform: translate(-50%,-50%) rotateX(51deg) rotateZ(0deg); }
}

/* ambient fill glow rings that grow with balance */
.yp-glow-ring {
  position: absolute;
  left:50%; top:50%;
  border-radius:50%;
  border: 1px solid rgba(255,216,107,var(--gop));
  transform: translate(-50%,-50%);
  pointer-events:none;
  transition: width 1.4s ease, height 1.4s ease, opacity 1.4s ease;
}

/* ── PARTICLES ── */
.yp-particle-field {
  position: absolute;
  inset: 0;
  z-index: 28;
  pointer-events: none;
}

.yp-particle {
  position: absolute;
  left: 50%; top: 50%;
  width: var(--sz); height: var(--sz);
  border-radius: 50%;
  opacity: 0;
  background: radial-gradient(
    circle at 30% 30%,
    #fff 0 14%,
    #ffe88a 32%,
    #c87a00 60%,
    transparent 76%
  );
  box-shadow:
    0 0 5px rgba(255,255,255,.9),
    0 0 14px rgba(255,200,60,.8);
  transform: translate(-50%,-50%) rotate(var(--ang)) translateX(var(--rad)) rotate(calc(var(--ang) * -1));
}
.yp-particle.orbit {
  animation: ypOrbit var(--ot) cubic-bezier(.37,0,.63,1) forwards;
}
.yp-particle.compress {
  animation: ypCompress var(--ct) cubic-bezier(.15,.65,.06,1) forwards;
}

@keyframes ypOrbit {
  0%   { opacity:0; transform:translate(-50%,-50%) rotate(var(--ang)) translateX(var(--rad)) rotate(calc(var(--ang)*-1)) scale(.2); }
  12%  { opacity:var(--op); }
  52%  { opacity:var(--op); transform:translate(-50%,-50%) rotate(calc(var(--ang)+150deg)) translateX(calc(var(--rad)*.96)) rotate(calc((var(--ang)+150deg)*-1)) scale(1); }
  100% { opacity:var(--op); transform:translate(-50%,-50%) rotate(calc(var(--ang)+340deg)) translateX(calc(var(--rad)*.78)) rotate(calc((var(--ang)+340deg)*-1)) scale(.8); }
}
@keyframes ypCompress {
  0%   { opacity:1; transform:translate(-50%,-50%) rotate(var(--ang2)) translateX(var(--rad2)) rotate(calc(var(--ang2)*-1)) scale(1); }
  30%  { transform:translate(-50%,-50%) rotate(calc(var(--ang2)+170deg)) translateX(calc(var(--rad2)*.45)) rotate(calc((var(--ang2)+170deg)*-1)) scale(1.08); }
  66%  { transform:translate(-50%,-50%) rotate(calc(var(--ang2)+350deg)) translateX(48px) rotate(calc((var(--ang2)+350deg)*-1)) scale(.82); }
  88%  { opacity:.96; transform:translate(-50%,-50%) rotate(calc(var(--ang2)+430deg)) translateX(17px) rotate(calc((var(--ang2)+430deg)*-1)) scale(.55); }
  100% { opacity:0; transform:translate(-50%,-50%) scale(0); filter:blur(8px); }
}

/* ── SHOCKWAVE on deposit ── */
.yp-shockwave {
  position:absolute; left:50%; top:50%;
  width:60px; height:60px;
  z-index:86;
  border:2px solid rgba(255,216,107,.95);
  border-radius:50%;
  opacity:0;
  transform:translate(-50%,-50%) scale(0);
  pointer-events:none;
}
.yp-shockwave.active {
  animation: ypShock 700ms ease-out forwards;
}
@keyframes ypShock {
  from { opacity:.95; transform:translate(-50%,-50%) scale(.2); }
  to   { opacity:0;   transform:translate(-50%,-50%) scale(18); }
}

/* ── SUPERNOVA flash on deposit ── */
.yp-supernova {
  position:absolute; left:50%; top:50%;
  width:26px; height:8px; z-index:90;
  opacity:0; pointer-events:none;
  transform:translate(-50%,-50%) scaleX(0);
}
.yp-supernova::before {
  content:"";
  position:absolute; left:50%; top:50%;
  width:100%; height:5px;
  transform:translate(-50%,-50%);
  border-radius:999px;
  background:white;
  box-shadow:
    0 0 7px #fff,
    0 0 24px #fff,
    0 0 60px rgba(255,220,80,.96),
    0 0 120px rgba(200,140,0,.92);
}
.yp-supernova::after {
  content:"";
  position:absolute; left:50%; top:50%;
  width:100%; height:46px;
  transform:translate(-50%,-50%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,200,60,.58),
    rgba(255,255,200,.96),
    rgba(255,200,60,.58),
    transparent
  );
  filter:blur(10px);
}
.yp-supernova.active {
  animation: ypNova 480ms cubic-bezier(.06,.88,.12,1) forwards;
}
@keyframes ypNova {
  0%  { opacity:0; transform:translate(-50%,-50%) scaleX(0); }
  10% { opacity:1; transform:translate(-50%,-50%) scaleX(.12); }
  34% { opacity:1; transform:translate(-50%,-50%) scaleX(5); }
  62% { opacity:.95; transform:translate(-50%,-50%) scaleX(22); }
  100%{ opacity:0; transform:translate(-50%,-50%) scaleX(52); }
}

/* ── GOLD MATTER EJECTION on deposit ── */
.yp-matter-field {
  position:absolute; inset:0; z-index:55; pointer-events:none;
}
.yp-matter {
  position:absolute; left:50%; top:50%;
  width:var(--sz); height:var(--sz);
  border-radius:50%; opacity:0;
  background:radial-gradient(circle at 30% 30%,#fff 0 12%,#ffe07a 32%,#c87a00 62%,transparent 78%);
  box-shadow:0 0 5px #fff,0 0 14px rgba(255,200,60,.92);
  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(3px);
}
.yp-matter.active {
  animation: ypMatter var(--dur) cubic-bezier(.08,.84,.13,1) forwards;
}
@keyframes ypMatter {
  0%  { opacity:0;  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(3px) scale(.1); }
  10% { opacity:1; }
  75% { opacity:1; }
  100%{ opacity:0;  transform:translate(-50%,-50%) rotate(var(--ang)) translateX(var(--dist)) scale(.42); }
}

/* ── BALANCE READOUT ── */
.yp-readout {
  position:absolute; inset:0;
  display:flex; flex-direction:column;
  align-items:center; justify-content:center;
  pointer-events:none; z-index:60;
  transform-style: preserve-3d;
}

/* ── DISTORTION ── */
.yp-distortion {
  position:absolute;
  width:900px; height:900px;
  border-radius:50%;
  z-index:4; pointer-events:none; opacity:0;
  background:radial-gradient(
    circle,
    transparent 0 17%,
    rgba(200,140,0,.07) 25%,
    transparent 43%
  );
  filter:blur(10px);
}
.yp-distortion.active {
  animation: ypDistort 4.6s ease-in-out forwards;
}
@keyframes ypDistort {
  0%  { opacity:0; transform:scale(.8); }
  12% { opacity:.85; transform:scale(1.03); }
  28% { opacity:.55; transform:scale(1.10); }
  46% { opacity:.15; transform:scale(.72); }
  62% { opacity:0;   transform:scale(.40); }
  76% { opacity:.75; transform:scale(.78); }
  100%{ opacity:0;   transform:scale(1.12); }
}

/* ── REBIRTH on deposit ── */
.yp-rebirth {
  position:absolute; left:50%; top:50%;
  width:40px; height:40px; z-index:52;
  border:2px solid rgba(255,216,107,.9);
  border-radius:50%; opacity:0;
  transform:translate(-50%,-50%) scale(0);
  pointer-events:none;
}
.yp-rebirth.active {
  animation: ypRebirth 1s cubic-bezier(.08,.82,.12,1) forwards;
}
@keyframes ypRebirth {
  0%  { opacity:0; transform:translate(-50%,-50%) scale(.05); filter:blur(5px); }
  24% { opacity:1; transform:translate(-50%,-50%) scale(.55); filter:blur(0); }
  62% { opacity:.85; transform:translate(-50%,-50%) scale(2.2); }
  100%{ opacity:0; transform:translate(-50%,-50%) scale(4.8); filter:blur(4px); }
}

/* ── DEPOSIT BUTTON ── */
.yp-btn {
  position: relative;
  width: 100%;
  max-width: 300px;
  padding: 16px 0;
  border-radius: 16px;
  background: #ffd86b;
  color: #0c0914;
  font-family: monospace;
  font-weight: 900;
  font-size: 13px;
  letter-spacing: .2em;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: background .15s, transform .1s, box-shadow .15s;
  box-shadow: 0 0 32px rgba(255,216,107,.28);
}
.yp-btn:hover:not(:disabled) {
  background: #ffe485;
  box-shadow: 0 0 44px rgba(255,216,107,.45);
}
.yp-btn:active:not(:disabled) {
  transform: scale(.97);
}
.yp-btn:disabled {
  background: rgba(255,216,107,.12);
  color: rgba(255,216,107,.25);
  cursor: not-allowed;
  box-shadow: none;
}

/* ── INPUT ── */
.yp-input {
  width: 100%;
  max-width: 300px;
  background: transparent;
  border: none;
  border-bottom: 2px solid rgba(255,216,107,.25);
  outline: none;
  color: #f5f0e8;
  font-family: monospace;
  font-weight: 900;
  font-size: 3rem;
  text-align: center;
  padding: 4px 28px 8px 4px;
  caret-color: #ffd86b;
  transition: border-color .2s;
}
.yp-input:focus { border-bottom-color: #ffd86b; }
.yp-input::placeholder { color: rgba(255,216,107,.1); }
.yp-input:disabled { opacity: .35; }
.yp-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.yp-input-unit {
  position: absolute;
  right: 4px;
  bottom: 12px;
  color: rgba(255,216,107,.35);
  font-family: monospace;
  font-size: .85rem;
  pointer-events: none;
}
`

// ── Animation helpers ─────────────────────────────────────────────────────────

function restart(el: HTMLElement | null, cls: string) {
  if (!el) return
  el.classList.remove(cls)
  void el.offsetWidth
  el.classList.add(cls)
}

function spawnParticles(field: HTMLElement, count = 160) {
  field.innerHTML = ''
  for (let i = 0; i < count; i++) {
    const p = document.createElement('div')
    const radius = 140 + Math.random() * 360
    const angle  = Math.random() * 360
    const size   = 1.5 + Math.random() * 5
    const op     = .35 + Math.random() * .65
    const ot     = 900 + Math.random() * 1400
    const ct     = 700 + Math.random() * 600
    p.className = 'yp-particle'
    p.style.setProperty('--rad', `${radius}px`)
    p.style.setProperty('--ang', `${angle}deg`)
    p.style.setProperty('--sz',  `${size}px`)
    p.style.setProperty('--op',  String(op))
    p.style.setProperty('--ot',  `${ot}ms`)
    p.style.setProperty('--ct',  `${ct}ms`)
    field.appendChild(p)
  }
  requestAnimationFrame(() => {
    Array.from(field.children).forEach((child, i) => {
      setTimeout(() => child.classList.add('orbit'), Math.random() * 600 + i * 2)
    })
  })
}

function compressParticles(field: HTMLElement) {
  Array.from(field.children).forEach((child, i) => {
    const el = child as HTMLElement
    const rad = el.style.getPropertyValue('--rad')
    const ang = parseFloat(el.style.getPropertyValue('--ang'))
    el.style.setProperty('--rad2', rad)
    el.style.setProperty('--ang2', `${ang + Math.random() * 90}deg`)
    setTimeout(() => {
      el.classList.remove('orbit')
      el.classList.add('compress')
    }, Math.random() * 400 + i * .7)
  })
}

function spawnMatter(field: HTMLElement, count = 130) {
  field.innerHTML = ''
  for (let i = 0; i < count; i++) {
    const p = document.createElement('div')
    const angle    = Math.random() * 360
    const distance = 200 + Math.random() * 440
    const dur      = 800 + Math.random() * 900
    const size     = 1.5 + Math.random() * 5.5
    p.className = 'yp-matter'
    p.style.setProperty('--ang',  `${angle}deg`)
    p.style.setProperty('--dist', `${distance}px`)
    p.style.setProperty('--dur',  `${dur}ms`)
    p.style.setProperty('--sz',   `${size}px`)
    field.appendChild(p)
    setTimeout(() => p.classList.add('active'), 400 + Math.random() * 500)
  }
}

// ── Main Component ────────────────────────────────────────────────────────────

export const YellowPoolTab: React.FC = () => {
  const [poolState, setPoolState] = useState<YellowTimePoolState | null>(null)
  const [loading, setLoading]     = useState(true)
  const [error, setError]         = useState<string | null>(null)
  const [hours, setHours]         = useState('')
  const [depositing, setDepositing] = useState(false)

  // DOM refs for animation targets
  const particleRef  = useRef<HTMLDivElement>(null)
  const matterRef    = useRef<HTMLDivElement>(null)
  const shockRef     = useRef<HTMLDivElement>(null)
  const novaRef      = useRef<HTMLDivElement>(null)
  const rebirthRef   = useRef<HTMLDivElement>(null)
  const distortRef   = useRef<HTMLDivElement>(null)
  const orbRef       = useRef<HTMLDivElement>(null)

  const balanceSec = poolState?.balance_seconds ?? 0
  const animated   = useAnimatedValue(balanceSec)

  // Orb ambient glow: 0h = dead, 100h = fully lit
  const MAX_H   = 100 * 3600
  const fillPct = Math.min(balanceSec / MAX_H, 1)

  useEffect(() => { load() }, [])

  // Inject CSS once
  useEffect(() => {
    const id = 'yp-styles'
    if (!document.getElementById(id)) {
      const s = document.createElement('style')
      s.id = id
      s.textContent = POOL_CSS
      document.head.appendChild(s)
    }
    return () => { /* leave styles — no other users */ }
  }, [])

  // Idle ambient particle loop
  useEffect(() => {
    let alive = true
    async function idleLoop() {
      while (alive) {
        if (particleRef.current) {
          spawnParticles(particleRef.current, 120)
          await delay(1200)
          if (!alive) break
          compressParticles(particleRef.current)
          await delay(3000)
        } else {
          await delay(1000)
        }
      }
    }
    idleLoop()
    return () => { alive = false }
  }, [])

  async function load() {
    setLoading(true); setError(null)
    try { setPoolState(await fetchPoolState()) }
    catch (e: any) { setError(e.message) }
    finally { setLoading(false) }
  }

  async function handleDeposit(e: React.FormEvent) {
    e.preventDefault()
    const h = parseFloat(hours)
    if (!h || h <= 0) { setError('Enter a valid number of hours'); return }

    setDepositing(true); setError(null)
    try {
      // Trigger full black-hole-style burst sequence
      if (distortRef.current) restart(distortRef.current, 'active')
      await delay(90)

      if (particleRef.current) spawnParticles(particleRef.current, 180)
      await delay(1050)
      if (particleRef.current) compressParticles(particleRef.current)
      await delay(280)

      // Shockwave + supernova
      if (shockRef.current)  restart(shockRef.current, 'active')
      if (novaRef.current)   restart(novaRef.current, 'active')
      await delay(480)

      // Gold matter ejection + rebirth ring
      if (matterRef.current)  spawnMatter(matterRef.current, 140)
      if (rebirthRef.current) restart(rebirthRef.current, 'active')

      // Persist to backend
      const state = await depositToPool({
        seconds: h * 3600,
        source: 'Manual Deposit',
        category: 'grind',
        speed: 1.0,
      })
      setPoolState(state)
      setHours('')
    } catch (e: any) {
      setError(e.message)
    } finally {
      setDepositing(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[500px]">
        <div className="text-center space-y-3">
          <div className="w-14 h-14 rounded-full border-2 border-[#ffd86b]/20 border-t-[#ffd86b] animate-spin mx-auto" />
          <p className="text-[#6b5a7f] font-mono text-[10px] tracking-widest uppercase">Initializing Pool</p>
        </div>
      </div>
    )
  }

  return (
    <div className="yp-scene py-8 px-4" style={{ minHeight: 600 }}>
      <div className="yp-stars" />

      {/* ── ORB ARENA ─────────────────────────────────────────────────── */}
      <div className="yp-orb-wrap" ref={orbRef} style={{ transformStyle: 'preserve-3d', perspective: '1000px' }}>

        {/* Ambient glow rings that swell with fill */}
        <div className="yp-glow-ring" style={{
          width:  `${380 + fillPct * 80}px`,
          height: `${380 + fillPct * 80}px`,
          '--gop': String(0.05 + fillPct * 0.2),
          transition: 'width 1.4s ease, height 1.4s ease, opacity 1.4s ease',
        } as React.CSSProperties} />
        <div className="yp-glow-ring" style={{
          width:  `${360 + fillPct * 50}px`,
          height: `${360 + fillPct * 50}px`,
          '--gop': String(0.08 + fillPct * 0.28),
        } as React.CSSProperties} />

        {/* Distortion */}
        <div className="yp-distortion" ref={distortRef} />

        {/* Orbiting rings */}
        <div className="yp-ring yp-ring-1" />
        <div className="yp-ring yp-ring-2" />
        <div className="yp-ring yp-ring-3" />
        <div className="yp-ring yp-ring-4" />

        {/* Event horizon core */}
        <div className="yp-core" />

        {/* Particle field */}
        <div className="yp-particle-field" ref={particleRef} />

        {/* Deposit burst effects */}
        <div className="yp-shockwave" ref={shockRef} />
        <div className="yp-supernova"  ref={novaRef} />
        <div className="yp-rebirth"    ref={rebirthRef} />
        <div className="yp-matter-field" ref={matterRef} />

        {/* Balance readout */}
        <div className="yp-readout">
          <p style={{ fontSize: 10, fontFamily: 'monospace', color: 'rgba(255,216,107,.45)', letterSpacing: '0.25em', textTransform: 'uppercase', marginBottom: 4 }}>
            Balance
          </p>
          <p style={{
            fontFamily: 'monospace',
            fontWeight: 900,
            fontSize: 'clamp(1.3rem,5vw,1.9rem)',
            color: '#ffd86b',
            lineHeight: 1,
            textShadow: `0 0 ${16 + fillPct * 24}px rgba(255,216,107,${0.35 + fillPct * 0.55})`,
            transition: 'text-shadow 1.4s ease',
          }}>
            {formatBalance(animated)}
          </p>
          <p style={{ fontSize: 10, fontFamily: 'monospace', color: 'rgba(255,216,107,.3)', marginTop: 6 }}>
            {(animated / 3600).toFixed(2)}h total
          </p>
        </div>
      </div>

      {/* ── INPUT + BUTTON ────────────────────────────────────────────── */}
      <form onSubmit={handleDeposit} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 16, width: '100%', marginTop: 8 }}>
        <div className="yp-input-wrap">
          <input
            type="number"
            min="0"
            step="0.25"
            value={hours}
            onChange={e => { setHours(e.target.value); setError(null) }}
            placeholder="0"
            disabled={depositing}
            className="yp-input"
          />
          <span className="yp-input-unit">h</span>
        </div>

        <button
          type="submit"
          disabled={depositing || !hours || parseFloat(hours) <= 0}
          className="yp-btn"
        >
          {depositing
            ? <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                <span style={{ width: 14, height: 14, borderRadius: '50%', border: '2px solid rgba(12,9,20,.3)', borderTopColor: '#0c0914', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
                Depositing
              </span>
            : '+ Deposit Hours'
          }
        </button>
      </form>

      {/* Error */}
      {error && (
        <p style={{ color: '#f87171', fontFamily: 'monospace', fontSize: 12, marginTop: 8, textAlign: 'center', maxWidth: 300 }}>{error}</p>
      )}

      {/* All-time total */}
      {poolState && poolState.total_earned_seconds > 0 && (
        <p style={{ color: 'rgba(255,216,107,.18)', fontFamily: 'monospace', fontSize: 10, letterSpacing: '0.2em', textTransform: 'uppercase', marginTop: 12, textAlign: 'center' }}>
          All-time — {formatBalance(poolState.total_earned_seconds)}
        </p>
      )}

      {/* Spin keyframe for deposit spinner */}
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  )
}

function delay(ms: number) {
  return new Promise<void>(r => setTimeout(r, ms))
}

