424	// ── Animation helpers ─────────────────────────────────────────────────────────
425	
426	function restart(el: HTMLElement | null, cls: string) {
427	  if (!el) return
428	  el.classList.remove(cls)
429	  void el.offsetWidth
430	  el.classList.add(cls)
431	}
432	
433	function spawnParticles(field: HTMLElement, count = 160) {
434	  field.innerHTML = ''
435	  for (let i = 0; i < count; i++) {
436	    const p = document.createElement('div')
437	    const radius = 140 + Math.random() * 360
438	    const angle  = Math.random() * 360
439	    const size   = 1.5 + Math.random() * 5
440	    const op     = .35 + Math.random() * .65
441	    const ot     = 900 + Math.random() * 1400
442	    const ct     = 700 + Math.random() * 600
443	    p.className = 'yp-particle'
444	    p.style.setProperty('--rad', `${radius}px`)
445	    p.style.setProperty('--ang', `${angle}deg`)
446	    p.style.setProperty('--sz',  `${size}px`)
447	    p.style.setProperty('--op',  String(op))
448	    p.style.setProperty('--ot',  `${ot}ms`)
449	    p.style.setProperty('--ct',  `${ct}ms`)
450	    field.appendChild(p)
451	  }
452	  requestAnimationFrame(() => {
453	    Array.from(field.children).forEach((child, i) => {
454	      setTimeout(() => child.classList.add('orbit'), Math.random() * 600 + i * 2)
455	    })
456	  })
457	}
458	
459	function compressParticles(field: HTMLElement) {
460	  Array.from(field.children).forEach((child, i) => {
461	    const el = child as HTMLElement
462	    const rad = el.style.getPropertyValue('--rad')
463	    const ang = parseFloat(el.style.getPropertyValue('--ang'))
464	    el.style.setProperty('--rad2', rad)
465	    el.style.setProperty('--ang2', `${ang + Math.random() * 90}deg`)
466	    setTimeout(() => {
467	      el.classList.remove('orbit')
468	      el.classList.add('compress')
469	    }, Math.random() * 400 + i * .7)
470	  })
471	}
472	
473	function spawnMatter(field: HTMLElement, count = 130) {
474	  field.innerHTML = ''
475	  for (let i = 0; i < count; i++) {
476	    const p = document.createElement('div')
477	    const angle    = Math.random() * 360
478	    const distance = 200 + Math.random() * 440
479	    const dur      = 800 + Math.random() * 900
480	    const size     = 1.5 + Math.random() * 5.5
481	    p.className = 'yp-matter'
482	    p.style.setProperty('--ang',  `${angle}deg`)
483	    p.style.setProperty('--dist', `${distance}px`)
484	    p.style.setProperty('--dur',  `${dur}ms`)
485	    p.style.setProperty('--sz',   `${size}px`)
486	    field.appendChild(p)
487	    setTimeout(() => p.classList.add('active'), 400 + Math.random() * 500)
488	  }
489	}
