493	export const YellowPoolTab: React.FC = () => {
494	  const [poolState, setPoolState] = useState<YellowTimePoolState | null>(null)
495	  const [loading, setLoading]     = useState(true)
496	  const [error, setError]         = useState<string | null>(null)
497	  const [hours, setHours]         = useState('')
498	  const [depositing, setDepositing] = useState(false)
