503	  const shockRef     = useRef<HTMLDivElement>(null)
504	  const novaRef      = useRef<HTMLDivElement>(null)
505	  const rebirthRef   = useRef<HTMLDivElement>(null)
506	  const distortRef   = useRef<HTMLDivElement>(null)
507	  const orbRef       = useRef<HTMLDivElement>(null)
508	
509	  const balanceSec = poolState?.balance_seconds ?? 0
510	  const animated   = useAnimatedValue(balanceSec)
511	
512	  // Orb ambient glow: 0h = dead, 100h = fully lit
513	  const MAX_H   = 100 * 3600
514	  const fillPct = Math.min(balanceSec / MAX_H, 1)
515	
516	  useEffect(() => { load() }, [])
517	
518	  // Inject CSS once
519	  useEffect(() => {
520	    const id = 'yp-styles'
521	    if (!document.getElementById(id)) {
522	      const s = document.createElement('style')
523	      s.id = id
524	      s.textContent = POOL_CSS
525	      document.head.appendChild(s)
526	    }
527	    return () => { /* leave styles — no other users */ }
528	  }, [])
529	
530	  // Idle ambient particle loop
531	  useEffect(() => {
532	    let alive = true
533	    async function idleLoop() {
534	      while (alive) {
535	        if (particleRef.current) {
536	          spawnParticles(particleRef.current, 120)
537	          await delay(1200)
538	          if (!alive) break
539	          compressParticles(particleRef.current)
540	          await delay(3000)
541	        } else {
542	          await delay(1000)
543	        }
544	      }
545	    }
546	    idleLoop()
547	    return () => { alive = false }
548	  }, [])
