557	  async function handleDeposit(e: React.FormEvent) {
558	    e.preventDefault()
559	    const h = parseFloat(hours)
560	    if (!h || h <= 0) { setError('Enter a valid number of hours'); return }
561	
562	    setDepositing(true); setError(null)
563	    try {
564	      // Trigger full black-hole-style burst sequence
565	      if (distortRef.current) restart(distortRef.current, 'active')
566	      await delay(90)
567	
568	      if (particleRef.current) spawnParticles(particleRef.current, 180)
569	      await delay(1050)
570	      if (particleRef.current) compressParticles(particleRef.current)
571	      await delay(280)
572	
573	      // Shockwave + supernova
574	      if (shockRef.current)  restart(shockRef.current, 'active')
575	      if (novaRef.current)   restart(novaRef.current, 'active')
576	      await delay(480)
577	
578	      // Gold matter ejection + rebirth ring
579	      if (matterRef.current)  spawnMatter(matterRef.current, 140)
580	      if (rebirthRef.current) restart(rebirthRef.current, 'active')
581	
582	      // Persist to backend
583	      const state = await depositToPool({
584	        seconds: h * 3600,
585	        source: 'Manual Deposit',
586	        category: 'grind',
587	        speed: 1.0,
